using LittleLeo.Events;
using NaughtyAttributes;
using UnityEngine;

namespace LittleLeo.Variables;

[CreateAssetMenu(menuName = "Variables References/Bool Reference")]
public class BoolReference : GameEvent<bool>
{
	[Header("Variable")]
	[SerializeField]
	[HideIf("allowBothSets")]
	private bool externalSet;

	[SerializeField]
	private bool allowBothSets;

	[SerializeField]
	[HideIf("externalSet")]
	private bool value;

	public bool Value => value;

	public void SetValue(bool value)
	{
		if (externalSet || allowBothSets)
		{
			this.value = value;
			Raise(value);
		}
		else
		{
			Debug.Log($"Cannot set {base.name} from external source, because bool externalSet is false");
		}
	}
}
